L5_1 = {}
L5_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE3_START@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 3900307
L5_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L5_1.m_Pos = "C"
L5_1.m_Talk_KOREA = "죽을 것 같지만……. 당장은 괜찮다고 해 둘게요."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "かなりまずい状態ではありますが……今のところは大丈夫だと言っておきます。"
L5_1.m_Talk_ENG = "Not really... But I’ll say that I am for now."
L5_1.m_Talk_TWN = "雖然快死掉了……現在就先當我沒事吧！"
L5_1.m_Talk_THA = "ก็ไม่เชิงนะ... แต่บอกว่าไม่เป็นไรก่อนแล้วกัน"
L5_1.m_Talk_VTN = "Không hẳn... Nhưng vẫn cầm cự được."
L5_1.m_Talk_SCN = "虽然感觉快要死了……但还能坚持。"
L5_1.m_Talk_DEU = "Ich sterbe gefühlt gleich ... Aber sagen wir mal, dass es mir okay geht."
L5_1.m_Talk_FRA = "C'est très douloureux mais... Je devrais m'en sortir."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE3_START@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 3900307
L6_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_SERIOUS"
L6_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L6_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L6_1.m_Pos = "R_M_I"
L6_1.m_Talk_KOREA = "부축해 드리겠습니다. 일어나세요, 실장님."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "さあ、手を。私が支えます、室長。"
L6_1.m_Talk_ENG = "Here, take my hand, Chief."
L6_1.m_Talk_TWN = "室長，我來扶你起來。"
L6_1.m_Talk_THA = "จับมือฉันสิหัวหน้า"
L6_1.m_Talk_VTN = "Đây, nắm lấy tay em, Trưởng Phòng."
L6_1.m_Talk_SCN = "我扶你吧。快站起来，室长。"
L6_1.m_Talk_DEU = "Ich stütze Sie. Stehen Sie auf, Frau Direktorin."
L6_1.m_Talk_FRA = "Je vais vous aider à vous relever."
L7_1 = {}
L7_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE3_START@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 3900307
L7_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L7_1.m_Pos = "C"
L7_1.m_Talk_KOREA = "고맙네요……. 배신자 딱지는 이제 떼도 될까요?"
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "ありがとうございます。裏切り者のレッテルはもう剥がしてもいいでしょうか？"
L7_1.m_Talk_ENG = "Thanks... Now, may I stop being called a traitor?"
L7_1.m_Talk_TWN = "謝謝……我現在可以撕掉叛徒的標籤了嗎？"
L7_1.m_Talk_THA = "ขอบคุณนะ... ตอนนี้หยุดเรียกฉันว่าคนทรยศได้รึยังล่ะ?"
L7_1.m_Talk_VTN = "Cảm ơn ... Bây giờ, chị có thể ngừng bị gọi là kẻ phản bội rồi chứ?"
L7_1.m_Talk_SCN = "谢谢……那我身上背叛者的标签，可以摘掉了吗？"
L7_1.m_Talk_DEU = "Danke ... Darf ich mich nun von dem Vorwurf des Verräters befreien?"
L7_1.m_Talk_FRA = "Merci... On peut m'enlever cette étiquette de traître, maintenant ?"
L8_1 = {}
L8_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE3_START@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 3900307
L8_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_LAUGH"
L8_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L8_1.m_Pos = "R"
L8_1.m_Talk_KOREA = "리더가 판단할 문제이지만 정신을 잃은 상태라서요. 무사히 돌아가면 그 때 얘기하죠."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "リーダーが判断すべき問題ですが、気を失った状態ですので。\n無事に帰ったらその時話しましょう。"
L8_1.m_Talk_ENG = "That’s for Leader to decide, but she’s kind of unconscious right now. We’ll talk about it once we’re out of here."
L8_1.m_Talk_TWN = "這必須由老大來判斷，但她現在尚未清醒。等安全回到公司後再說吧。"
L8_1.m_Talk_THA = "นั่นก็แล้วแต่ท่านผู้นำนะ แต่ตอนนี้เหมือนเธอจะไม่ได้สติอยู่ ออกจากที่นี่แล้วค่อยว่ากัน"
L8_1.m_Talk_VTN = "Việc đó để Thủ Lĩnh quyết định, nhưng hiện tại cô ấy đang bất tỉnh. Chúng ta sẽ nói về nó sau khi ra khỏi đây."
L8_1.m_Talk_SCN = "这是队长要判断的问题，可她现在失去了意识。等安全返回后再说吧。"
L8_1.m_Talk_DEU = "Das muss die Anführerin entscheiden, aber sie ist ohnmächtig. Reden wir darüber, wenn wir zurück sind."
L8_1.m_Talk_FRA = "Ça, c'est à la chef de décider. Nous en reparlerons si nous rentrons tous sains et saufs, quand elle reprendra conscience..."
L9_1 = {}
