L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "今はのんびりおしゃべりをしている場合ではありませんので。"
L9_1.m_Talk_ENG = "Right now, there are other matters to attend to."
L9_1.m_Talk_TWN = "現在還不是悠哉聊天的時候。"
