L9_1.m_Talk_SCN = "现在可不是闲聊的时候。"
L9_1.m_Talk_DEU = "Nun ist keine Zeit für Plaudereien."
L9_1.m_Talk_FRA = "Pas de temps à perdre en bavardages."
