L14_1 = {}
L14_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE3_START@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 3900307
L14_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_IDLE"
L14_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L14_1.m_Pos = "C"
L14_1.m_Talk_KOREA = "내가 카운터란 게 처음으로 고마운 순간이었어. 일반인이면 뼛가루도 안 남았을 테니까."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "私がカウンターであることに初めて感謝した瞬間だったわ。\n一般人なら骨すら残っていなかった。"
L14_1.m_Talk_ENG = "This is the first time I’m glad that I’m a Counter. A normal person would’ve died from that attack."
L14_1.m_Talk_TWN = "我還是第一次覺得還好她是制裁者，否則要是普通人的話，應該早就屍骨無存吧？"
L14_1.m_Talk_THA = "นี่เป็นครั้งแรกเลยนะที่ฉันดีใจที่ตัวเองเป็นเคาน์เตอร์ คนธรรมดาโดนแบบนั้นคงตายไปแล้ว"
L14_1.m_Talk_VTN = "Đây là lần đầu tiên tao vui sướng vì là một Counter. Một người bình thường sẽ chết vì đòn ấy."
L14_1.m_Talk_SCN = "我第一次对自己是制裁者而感到庆幸。如果我是普通人，现在应该连渣都不剩了吧。"
L14_1.m_Talk_DEU = "Ich war zum ersten Mal froh darüber, ein Counter zu sein. Als normale Person wäre von mir nicht mal ein Häufchen Staub übriggeblieben."
L14_1.m_Talk_FRA = "Heureusement que je suis un Counter... Sinon, j'aurais été réduite en cendres."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE3_START@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 3900307
L15_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_PRIDE"
L15_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L15_1.m_Talk_KOREA = "체크메이트까지는…… 한 수 모자랐지만 말이지."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "チェックメイトまでは……一手及ばなかったけどね。"
L15_1.m_Talk_ENG = "Guess you were one move off from a checkmate."
L15_1.m_Talk_TWN = "雖然離將軍……還差一步。"
L15_1.m_Talk_THA = "ท่าทางเธอเดินอีกตาเดียวก็รอดจากรุกจนได้แล้ว"
L15_1.m_Talk_VTN = "Tao đoán mày đã chiếu tướng lệch một nước rồi."
L15_1.m_Talk_SCN = "想要将死我……你们还棋差一着。"
L15_1.m_Talk_DEU = "Allerdings hat zum Schachmatt ... die entscheidende Taktik gefehlt."
L15_1.m_Talk_FRA = "Dommage, plus qu'un coup et c'était... Échec et mat."
