L18_1.m_Face = "UNIT_SERIOUS"
L18_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L18_1.m_Pos = "C"
L18_1.m_Talk_KOREA = "이제 포기하세요, 바이오닉스 대표."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "もう観念してください、バイオニクス代表。"
L18_1.m_Talk_ENG = "Surrender yourself, CEO of Bionics."
L18_1.m_Talk_TWN = "仿生代表，收手吧！"
