L18_1.m_Talk_DEU = "Geben Sie es auf, Vorsitzende von Bionix."
L18_1.m_Talk_FRA = "Je crois que vous devriez vous arrêtez là, Cecilia."
L19_1 = {}
L19_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE3_START@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 3900307
L19_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L19_1.m_Pos = "C"
L19_1.m_Crash = 30
L19_1.m_Talk_KOREA = "그 장치 없이는…… 아가씨에게 더 이상 암시를 걸 수 없는 것 아닌가요?"
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "その装置が無ければ……お嬢様にこれ以上暗示をかけられないのでは？"
L19_1.m_Talk_ENG = "Without that... You can no longer control Miss Jia."
L19_1.m_Talk_TWN = "沒有那個裝置……你就無法再對小姐下令吧？"
L19_1.m_Talk_THA = "ไม่มีเข็มกลัดนั่น... เธอก็ควบคุมคุณเจียไม่ได้แล้ว"
L19_1.m_Talk_VTN = "Nếu không có thứ đó... Cô không thể kiểm soát cô Jia nữa."
L19_1.m_Talk_SCN = "没有那个胸针……你就不能继续给小姐发送命令了，不是吗？"
L19_1.m_Talk_DEU = "Ohne dieses Gerät ... können Sie das Fräulein nicht mehr steuern, nicht wahr?"
L19_1.m_Talk_FRA = "Vous ne pouvez plus la contrôler sans cet appareil... Si ?"
