L23_1 = {}
L23_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE3_START@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 3900307
L23_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_SERIOUS"
L23_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L23_1.m_Pos = "C"
L23_1.m_Talk_KOREA = "그래. 하지만 너희들이 가진 패도 전부 바닥난 것 같은데."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "そうね。でも、あんたたちが持っている手札も底をついたようだけど。"
L23_1.m_Talk_ENG = "True, but I believe you’ve also showed me your hand too, no?"
L23_1.m_Talk_TWN = "話是沒錯，不過你們牌都已經出了吧？"
L23_1.m_Talk_THA = "ก็จริง แต่ดูทรงเธอคงเผยไต๋ออกมาหมดแล้วสินะ จริงมั้ย?"
L23_1.m_Talk_VTN = "Đúng, nhưng tao tin rằng mày cũng lật tẩy rồi, đúng không?"
L23_1.m_Talk_SCN = "没错。但你们手中也没有底牌了吧。"
L23_1.m_Talk_DEU = "Stimmt. Aber ihr scheint auch eure letzten Karten verspielt zu haben ..."
L23_1.m_Talk_FRA = "Peut-être mais vous non plus, vous n'avez plus de cartes à jouer, je me trompe ?"
