L29_1 = {}
L29_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE3_START@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 3900307
L29_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_IDLE"
L29_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L29_1.m_Pos = "C"
L29_1.m_Talk_KOREA = "원래 계획은 지아가 직접 너희를 전부 죽이게 만드는 거였지만……"
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "元の計画だと、ユイちゃんの手であんたたちを皆殺しにする予定だったけど……"
L29_1.m_Talk_ENG = "I was originally going to make Jia kill all of you..."
L29_1.m_Talk_TWN = "雖然照原本的計畫，是要讓小佳親手殺光你們……"
L29_1.m_Talk_THA = "ทีแรกฉันว่าจะให้เจียฆ่าเธอซะ..."
L29_1.m_Talk_VTN = "Tao vốn định bắt Jia giết tất cả bọn mày..."
L29_1.m_Talk_SCN = "原本计划让小佳亲自杀掉你们所有人……"
L29_1.m_Talk_DEU = "Mein Plan war, dass Jia euch alle eigenhändig tötet ..."
L29_1.m_Talk_FRA = "Normalement j'avais prévu que Jia vous tue mais..."
L30_1 = {}
L30_1.m_CutScenKey_Talk = "ALPHA_ACT3_STAGE3_START@30#Talk"
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 3900307
L30_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_PRIDE"
L30_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L30_1.m_Pos = "C"
L30_1.m_Crash = 20
L30_1.m_Talk_KOREA = "어쩔 수 없지. 나도 이번 대국에 전부를 걸었거든."
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "仕方ないわね。私も今回の対局に全てを賭けたもの。"
L30_1.m_Talk_ENG = "But, you know, I'm all in on this as well."
L30_1.m_Talk_TWN = "不過沒辦法，畢竟我也是賭上我的一切。"
L30_1.m_Talk_THA = "แต่ว่านะ ฉันเองก็ทุ่มหมดหน้าตักเหมือนกัน"
L30_1.m_Talk_VTN = "Nhưng, bọn mày biết đấy, tao đã đặt cược hết tất cả vào vụ này rồi."
L30_1.m_Talk_SCN = "但没办法。我已经在对局中压上了全部。"
L31_1 = "Aber was soll‘s. Auch ich habe alles auf diese Partie gesetzt."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je n'ai plus le choix. Parce que j'ai tout misé sur cette partie."
L30_1.m_Talk_FRA = L31_1
