L45_1 = "ALPHA_ACT3_STAGE3_START@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3900307
L44_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_SERIOUS"
L44_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L44_1.m_Pos = "C"
L45_1 = "이것들은 실험관 바깥에선 유통기한도 짧고 생산 단가까지 비싼 결함투성이야."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "こいつらは実験室の外では使用期限も短いし、生産単価も高い欠陥だらけ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "These things don’t last long outside of their vats, are expensive to make, and are riddled with flaws."
L44_1.m_Talk_ENG = L45_1
L45_1 = "這些是效期短，而且製造成本又高的瑕疵品。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ร่างโคลนพวกนี้พอออกมาแล้วก็อยู่ได้ไม่นาน ค่าสร้างขึ้นมาก็แพง แถมตำหนิรุงรังไปหมด"
L44_1.m_Talk_THA = L45_1
L45_1 = "Những thứ này không thể tồn tại lâu bên ngoài những bộ áo giáp của chúng. Chúng rất đắt tiền, và đầy lỗ hổng."
L44_1.m_Talk_VTN = L45_1
L45_1 = "她们走出试管后可活动的寿命很短，是造价高昂还带有很多缺陷的残次品。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Die da sind außerhalb ihrer Testapparaturen nur kurzzeitig haltbar, teuer herzustellen und voller Fehler."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Ces clones défectueux ne durent pas longtemps une fois sortis du laboratoire. Et en plus, ils coûtent cher !"
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "ALPHA_ACT3_STAGE3_START@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3900307
L45_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L45_1.m_Pos = "C"
L45_1.m_Crash = 10
L46_1 = "이런 식의 물량전은 내 취향이 아니지만…… 인정해 주지."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "こんな物量作戦は私の好みではないけど……認めてあげるわ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I’m not one to play the numbers game, but... I’ll admit."
L45_1.m_Talk_ENG = L46_1
L46_1 = "雖然我不是很喜歡以多欺少……但承認吧！"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ฉันไม่ใช่พวกชอบแทงหวยหรอก... แต่ก็ต้องยอมรับแหละ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tao không phải là người chơi trò đếm số, nhưng... tao sẽ thừa nhận."
L45_1.m_Talk_VTN = L46_1
L46_1 = "这种方式的人海战术虽然不是我偏好的策略，但不得不承认……"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Eine Materialschlacht wie diese ist nicht mein Stil ... Aber ich gestehe ein,"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Je dois avouer que les batailles de machines ne sont pas vraiment ma tasse de thé..."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "ALPHA_ACT3_STAGE3_START@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3900307
L46_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_PRIDE"
L46_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L46_1.m_Pos = "C"
L47_1 = "지금은 승부의 취향을 따질 때가 아니라는 걸."
