L4_1 = "돌이켜 보면, 할아버님께선 늘 혼자셨다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "m_bTalkCenterFadeIn"
L3_1[L4_1] = true
L4_1 = "振り返ってみれば、お祖父様はいつも一人だった。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Looking back, Grandfather was always alone."
L3_1.m_Talk_ENG = L4_1
L4_1 = "回想起來，爺爺總是自己一個人。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "นึกย้อนไปแล้ว คุณปู่ของฉันอยู่คนเดียวเสมอ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Nghĩ lại thì ông nội mình luôn luôn đơn độc."
L3_1.m_Talk_VTN = L4_1
L4_1 = "现在回想起来，爷爷总是一个人。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wenn ich so zurückdenke, war Großvater immer alleine."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Quand on j'y pense, grand-père était toujours tout seul."
L3_1.m_Talk_FRA = L4_1
