L5_1 = "할아버님께 쉽게 말을 붙이는 사람도 없었고."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "m_bTalkCenterFadeIn"
L4_1[L5_1] = true
L5_1 = "お祖父様に気軽に話しかける人もいなかったし、"
L4_1.m_Talk_JPN = L5_1
L5_1 = "No one really chatted with him."
L4_1.m_Talk_ENG = L5_1
L5_1 = "沒有人敢跟爺爺對話，"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ไม่มีใครคุยกับท่านจริงๆ จังๆ เลย"
L4_1.m_Talk_THA = L5_1
L5_1 = "Không ai thực sự trò chuyện với ông ấy."
L4_1.m_Talk_VTN = L5_1
L5_1 = "没有人找爷爷聊天。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Niemand sprach ihn einfach mal nett an,"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Personne n'osait l'approcher..."
L4_1.m_Talk_FRA = L5_1
