L14_1 = "아, 아들아……. 안 돼, 어떻게, 어떻게……!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "む、息子よ……ダメだ、なんてことだ……！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "N... no my boy ... this can't be…!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "我…我的兒子……不可以，怎麼會……！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ละ-ลูก... ไม่นะ! ทำไมถึง...?!"
L13_1.m_Talk_THA = L14_1
L14_1 = "C-con trai... Không! Sao con có thể...?!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "儿子……不，不，为什么！为什么……！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Oh, mein Sohn ... nein, wieso, wie ...!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "N-Non... Mon fils... Non !"
L13_1.m_Talk_FRA = L14_1
