L15_1 = "CEO_NPC_ALPHA_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "새아가! 새아가는 어디 있니!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "嫁は、あの子はどこにいる！？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Anyone...! Anyone have seen Shin family?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "媳婦！我的媳婦呢！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "หนู...! หนูอยู่ไหนลูก?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Đứa trẻ...! Cháu đang ở đâu?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "孩子！我的儿媳妇在哪里？！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Wo ist meine Schwiegertochter? Wo bist du?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Où est ma belle-fille ? Où est-elle ?"
L14_1.m_Talk_FRA = L15_1
