L16_1 = "CEO_NPC_ALPHA_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "이런 걸, 이런 걸 바란 게 아니었는데……. 이런 건 아니었어……. 이런 건……."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "こんなことを、こんなことを望んだわけではない……\nこんなはずではない……こんな……"
L15_1.m_Talk_JPN = L16_1
L16_1 = "This… This was not meant to be…"
L15_1.m_Talk_ENG = L16_1
L16_1 = "這…這不是我要的……不是這樣……不是……"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ผม... ไม่ได้อยาก... ให้เป็นแบบนี้เลย..."
L15_1.m_Talk_THA = L16_1
L16_1 = "Mình... đã không muốn... bất kỳ điều gì như thế này..."
L15_1.m_Talk_VTN = L16_1
L16_1 = "这、这不是我希望的……不是这样的……不是……"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Das wollte ich nicht ... das wollte ich wirklich nicht ... das nicht ..."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Ce n'est pas ce que je voulais... Pas ça.... Pas ça..."
L15_1.m_Talk_FRA = L16_1
