L21_1.m_CharStrID = L22_1
L22_1 = "F 타입……. 아니, 지, 지아야……. 그게 무슨 꼴이니?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "Fタイプ……いや、ユ、ユイ……その格好は？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Type-F... I-I mean, Jia... What happened to you?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "F型……不是，小佳……你那是怎麼回事？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ประเภท-F... อะ-เอ้อ เจีย... หนูเป็นอะไรน่ะ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Loại-F... Ý ta là, Jia... Chuyện gì đã xảy ra với cháu thế?"
