L23_1[L24_1] = L25_1
L24_1 = "할아버님 보여드리려고 펼쳤어요. 반짝거려서 예쁘죠, 할아버님?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "お祖父様にお見せしようと広げてみました。\nキラキラして綺麗でしょう、お祖父様？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I wanted you to see them. Aren’t they pretty how they sparkle, Grandfather?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "爺爺你看我的翅膀，亮亮的很漂亮吧？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "หนูอยากให้ปู่เห็นค่ะ เป็นประกายสวยดีใช้มั้ยคะคุณปู่?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Cháu muốn ông nhìn thấy chúng. Không phải chúng lấp lánh đẹp quá sao ạ, Ông ơi?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "我想把它给爷爷看看，所以才展开的。闪闪发光的，是不是很漂亮呀，爷爷？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Ich habe sie ausgebreitet, um sie Ihnen zu zeigen. Sie glitzern schön, oder?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "C'est pour vous les montrer, grand-père. Vous avez vu comme elles brillent ? C'est joli !"
L23_1.m_Talk_FRA = L24_1
