L25_1 = "CEO_NPC_ALPHA_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "마, 말도 안 돼……. 그 지도는 참고만 했을 뿐인데, 어떻게……."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "あ、あり得ない……あの地図は参考にしただけなのに、どうやって……"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I-impossible... I just used that map as reference... But how...?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "這…這怎麼可能……那個圖譜只是用來參考的而已，怎麼會……"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ปะ-เป็นไปไม่ได้... ฉันก็อ้างอิงตามผังนั่น... แต่ทำไม...?"
L24_1.m_Talk_THA = L25_1
L25_1 = "K-không thể nào... Ta chỉ sử dụng bản đồ đó làm tài liệu tham khảo... Nhưng sao...?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "不、不可能……只是将那个组图作为参考而已，怎么会……"
L24_1.m_Talk_SCN = L25_1
L25_1 = "D-das gibt‘s doch nicht ... Diese Karte war nur eine Referenz, wie konnte das ..."
L24_1.m_Talk_DEU = L25_1
L25_1 = "I-Impossible...! Ces instructions n'étaient qu'une référence... Mais pourquoi..."
L24_1.m_Talk_FRA = L25_1
