L26_1 = "CEO_NPC_ALPHA_NULL"
L25_1.m_CharStrID = L26_1
L26_1 = "설마…… 연구원들이 서로 싸우던 이유가……!?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "まさか……研究員たちが争っていた理由は……！？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Is this... what the researchers were fighting over...?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "難道……研究員互毆的原因是……？！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "นี่เหรอ... ที่ทำให้พวกนักวิจัยทะเลาะกัน...?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Đây có phải là... điều mà các nhà nghiên cứu đang tranh cãi không...?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "难道……研究员们互相打斗的原因就是……！？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Herrje ... War das der Grund, warum sich die Forscher gestritten haben ...?!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Alors... Est-ce que les chercheurs se sont disputés à cause de..."
