L29_1[2] = L31_1
L27_1[L28_1] = L29_1
L28_1 = "아, 맞다. 제가 이 날개로 할아버님이 원하는 건 뭐든 이루어 드릴게요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "あ、そうだ。私がこの翅でお祖父様が願うことを何でも叶えてあげます。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Oh, right. I’ll grant you anything you wish with these wings."
L27_1.m_Talk_ENG = L28_1
L28_1 = "對了，爺爺，我可以用這雙翅膀，替爺爺達成所有願望喔～"
L27_1.m_Talk_TWN = L28_1
L28_1 = "อ๋อ จริงด้วย คุณปู่อยากได้อะไรหนูจะใช้ปีกนี้เสกให้นะคะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "À, đúng rồi. Cháu sẽ ban cho ông bất kỳ điều ước gì với đôi cánh nào."
L27_1.m_Talk_VTN = L28_1
L28_1 = "啊，对了。我可以用这个翅膀给爷爷实现任何愿望哦。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ach, stimmt ja. Ich erfülle Ihnen mit diesen Flügeln jeden Wunsch, Großvater."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ah, au fait ! Avec ces ailes, je réaliserai tout ce que vous voulez."
L27_1.m_Talk_FRA = L28_1
