L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "JIA_CHILD_ALPHA_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "다른 분들에게는 이미 전부……."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "他の方々の願いはもう全部……"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I’ve already granted everyone else’s..."
L28_1.m_Talk_ENG = L29_1
L29_1 = "其他人的願望我已經全部……"
L28_1.m_Talk_TWN = L29_1
L29_1 = "หนูทำให้คนอื่นไปแล้ว..."
L28_1.m_Talk_THA = L29_1
L29_1 = "Cháu đã ban điều ước cho những người khác..."
L28_1.m_Talk_VTN = L29_1
L29_1 = "其他人的愿望已经全都……"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Für die anderen Leute habe ich bereits alle ..."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Et les autres..."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "ALPHA_ACT3_STAGE3_START@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
