L31_1 = "JIA_CHILD_ALPHA_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "네? 왜요?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "はい？　どうしてですか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Huh? Why not?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "為什麼？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เอ๋? ทำไมล่ะคะ?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Dạ? Tại sao không ạ?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "嗯？为什么？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wie bitte? Warum nicht?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Pardon ? Pourquoi ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "ALPHA_ACT3_STAGE3_START@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3900307
L31_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_BGCrash = 20
L31_1.m_fBGCrashTime = 1
L32_1 = "CEO_NPC_ALPHA_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "그 날개를 펼치면 안 돼. 쓰면 쓸수록 널 점점 사람에서 멀어지게 만들 거다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "その翅を広げてはならないのだ！\n使えば使うほど、お前を『人』からどんどん遠ざけてしまうぞ！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "You must not use your wings. The more you use them, you will drift further away from humanity."
L31_1.m_Talk_ENG = L32_1
L32_1 = "你不可以展開那雙翅膀，這樣會讓你離人類越來越遠！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "หนูจะใช้ปีกไม่ได้นะ ยิ่งใช้หนูจะยิ่งห่างไกลความเป็นมนุษย์นะลูก"
L31_1.m_Talk_THA = L32_1
L32_1 = "Cháu không được sử dụng đôi cánh của mình. Cháu càng sử dụng chúng, cháu sẽ càng rời xa nhân loại."
L31_1.m_Talk_VTN = L32_1
L32_1 = "不可以展开那对翅膀！因为你使用的次数越多，失去的人性也就越多。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Du darfst diese Flügel nicht ausbreiten. Je mehr du sie benutzt, desto ferner wirst du dich von den Menschen entfernen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Plus tu utiliseras tes ailes, plus tu perdras ton humanité."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "ALPHA_ACT3_STAGE3_START@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3900307
L32_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "JIA_CHILD_ALPHA_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "하지만…… 다들 좋아했는걸요?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "でも……みんな喜んでいましたよ？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "But... Everyone else likes it..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "可是……大家都很開心呢？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แต่ว่า... ทุกคนชอบนี่คะ..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Nhưng... những người khác đều thích nó mà ạ..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "但是……大家都很高兴啊？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Aber ... alle haben sich gefreut!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Mais... tout le monde les aime, pourtant !"
L32_1.m_Talk_FRA = L33_1
