L36_1 = "ALPHA_ACT3_STAGE3_START@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3900307
L35_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "CEO_NPC_ALPHA_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "……지아야, 보이니?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "……ユイ、見えるか？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Jia... Do you see it?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "……小佳，你有看到嗎？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เจีย... หนูเห็นมั้ยลูก?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Jia... Cháu có thấy nó không?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "……小佳，看到了吗？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "... Jia, siehst du nicht?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "... Tu vois, Jia ?"
L35_1.m_Talk_FRA = L36_1
