L37_1 = "ALPHA_ACT3_STAGE3_START@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3900307
L36_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "CEO_NPC_ALPHA_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "인간은……. 이렇게 쉽게 상처 입는 나약한 종이란다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "人間は……いとも簡単に傷ついてしまう、弱い生き物だ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Us humans... We are fragile beings."
L36_1.m_Talk_ENG = L37_1
L37_1 = "人類……就是如此軟弱無能的族類。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "มนุษย์เรา... เป็นสิ่งมีชีวิตที่เปราะบาง"
L36_1.m_Talk_THA = L37_1
L37_1 = "Loài người chúng ta... Chúng ta là những sinh vật yếu đuối."
L36_1.m_Talk_VTN = L37_1
L37_1 = "人类……就是如此容易受伤的脆弱种族。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Menschen sind ... verletzliche, schwache Wesen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Les êtres humains sont des êtres faibles, fragiles."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "ALPHA_ACT3_STAGE3_START@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3900307
L37_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "CEO_NPC_ALPHA_NULL"
L37_1.m_CharStrID = L38_1
L38_1 = "그래서 상처를 입는 게 두려운 나머지, 자신과 다른 존재를 구별하고 솎아내려 해."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "だから傷つくことを恐れるあまり、自分とは異なる存在を区別し、排除しようとする。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "For fear of getting hurt, we try to differentiate ourselves from others unlike us."
L37_1.m_Talk_ENG = L38_1
L38_1 = "所以害怕受傷之餘，還會排擠和自己不同的種類。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เรากลัวจะต้องเจ็บปวด เลยพยายามแบ่งแยกตัวเองจากคนที่ไม่เหมือนเรา"
L37_1.m_Talk_THA = L38_1
L38_1 = "Vì sợ bị tổn thương, chúng ta cố gắng giữ khoảng cách với những người khác không giống như chúng ta."
L37_1.m_Talk_VTN = L38_1
L38_1 = "因为害怕受伤，他们会竭尽全力地排斥和自己不一样的存在。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Sie fürchten sich so sehr davor, verletzt zu werden, sodass Sie andere Wesen diskriminieren wollen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Et ils ont tellement peur de se blesser qu'ils se distinguent des autres pour les abaisser."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
