L40_1 = "ALPHA_ACT3_STAGE3_START@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3900307
L39_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "CEO_NPC_ALPHA_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "지아야, 네가 가진 힘은 사람들을 위해 쓰여야 한단다. 할애비 말, 무슨 뜻인지 알지?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "ユイ、お前が持つ力は人々のために使われるべきだ。\n私の言葉がどういう意味か、わかるね？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Jia, you must use your powers for humanity. Do you understand your grandpa?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "小佳，你的能力必須用來幫助人，你有聽懂爺爺的意思吧？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เจีย หนูต้องใช้พลังเพื่อมนุษย์นะลูก เข้าใจปู่มั้ย?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Jia, cháu phải sử dụng sức mạnh của mình vì nhân loại. Cháu có hiểu ông nói gì không nào?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "小佳，你拥有的力量要用在正确的地方。你能理解我说的话，是什么意思吧？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Jia, deine Kräfte müssen den Menschen zuliebe eingesetzt werden. Verstehst du, was ich meine, mein Kind?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Jia, tu dois utiliser ta force pour aider les autres. Tu m'as bien compris ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "ALPHA_ACT3_STAGE3_START@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3900307
L40_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "JIA_CHILD_ALPHA_NULL"
L40_1.m_CharStrID = L41_1
L41_1 = "네. 아빠도 말씀하셨어요. 밖에 나가서 모두를 행복하게 만들어 주면, 친구도 많이 사귈 수 있을 거라고요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "はい。お父様もおっしゃいました。外に出てみんなを幸せにしてあげれば、\nお友達もたくさん作れるそうです。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Yes. Father told me that if I make everyone in the world happy, I'll make a lot of friends."
L40_1.m_Talk_ENG = L41_1
L41_1 = "懂，爺爺有說，等我出去後，只要讓大家幸福，就可以交到很多朋友。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เข้าใจค่ะ พ่อบอกว่าถ้าหนูทำให้ทุกคนในโลกมีความสุข หนูก็จะมีเพื่อนเยอะแยะเลย"
L40_1.m_Talk_THA = L41_1
L41_1 = "Vâng. Cha nói với cháu rằng nếu cháu làm cho tất cả mọi người trên thế giới hạnh phúc, cháu sẽ có rất nhiều bạn bè."
L40_1.m_Talk_VTN = L41_1
L41_1 = "是的。父亲也曾经说过。到外边后，如果让大家都变得幸福，就能交到很多朋友。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ja. Das sagte auch mein Papa. Dass ich viele Freunde finden werde, wenn ich da draußen alle Leute glücklich mache."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Oui. Père m'a dit que si je pourrai me faire beaucoup d'amis si je parviens à rendre les gens heureux."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "ALPHA_ACT3_STAGE3_START@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3900307
L41_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "CEO_NPC_ALPHA_NULL"
L41_1.m_CharStrID = L42_1
L42_1 = "그래…… 그렇지…… 착하구나, 지아야. 참 착해. "
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "そうか……そうだな……いい子だ、ユイ。本当にいい子だ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Good... You’re a good girl, Jia."
L41_1.m_Talk_ENG = L42_1
L42_1 = "對……沒錯……小佳，真乖～"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ดีมาก... หนูเก่งมากลูก เจีย"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tốt lắm... Cháu là một cô bé ngoan, Jia."
L41_1.m_Talk_VTN = L42_1
L42_1 = "是啊……嗯……你真善良，小佳真善良。 "
L41_1.m_Talk_SCN = L42_1
L42_1 = "Ja ... genau ... Ein liebes Kind bist du, Jia, wirklich."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Oui... C'est ça... Tu es vraiment une gentille fille, Jia. "
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "ALPHA_ACT3_STAGE3_START@92#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 92
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3900307
L42_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "CEO_NPC_ALPHA_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "하지만 <color=#ffd34c>그건</color>…… 너를 두렵고 배척해야 할 존재로 만들 거란다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "だが、<color=#ffd34c>それ</color>は……\nお前を恐るべき存在、排斥すべき存在に変えてしまうだろう。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "But <color=#ffd34c>those</color>... are what will make people fear and alienate you."
L42_1.m_Talk_ENG = L43_1
L43_1 = "可是，<color=#ffd34c>那個</color>……會讓人家害怕你，甚至是排擠你。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "แต่<color=#ffd34c>นั่น</color>... จะทำให้คนกลัวและออกห่างจากหนูนะลูก"
L42_1.m_Talk_THA = L43_1
L43_1 = "Nhưng <color=#ffd34c>chúng</color>... là những thứ sẽ khiến mọi người sợ hãi và xa lánh cháu."
L42_1.m_Talk_VTN = L43_1
L43_1 = "但<color=#ffd34c>翅膀</color>……只会让你成为别人恐惧和排斥的存在。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Aber <color=#ffd34c>das</color> ... wird dich zu einem Wesen machen, das man fürchten und abgrenzen muss."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Mais <color=#ffd34c>cette chose</color>... Ne provoquera que la crainte autour de toi. Elles feront de toi un monstre, et tu seras exclue."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "ALPHA_ACT3_STAGE3_START@93#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 93
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3900307
L43_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "JIA_CHILD_ALPHA_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "그러면…… 저는 어떻게 해야 돼요, 할아버님?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "それでは……私はどうすればいいのですか、お祖父様？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Then... What am I supposed to do, Grandfather?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "那……爺爺，小佳該怎麼辦呢？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ถ้าอย่างนั้น... หนูควรทำยังไงดีคะคุณปู่?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Vậy thì... Cháu phải làm gì ạ, ông nội?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "那…… 我该怎么办呢，爷爷？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Was ... muss ich dann tun, Großvater?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Mais alors... que dois-je faire ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "ALPHA_ACT3_STAGE3_START@94#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 94
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3900307
L44_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "CEO_NPC_ALPHA_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "요정이 아니라, 사람으로서 살아가야지. "
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "妖精ではなく、人として生きていかねばならない。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You must live as a human being, not as a fairy."
L44_1.m_Talk_ENG = L45_1
L45_1 = "你不能當精靈，你要用人類的身分活下去，"
L44_1.m_Talk_TWN = L45_1
L45_1 = "หนูต้องใช้ชีวิตแบบมนุษย์ไง ไม่ใช่นางฟ้า"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cháu phải sống như một con người, không phải như một nàng tiên."
L44_1.m_Talk_VTN = L45_1
L45_1 = "不要成为妖精，而是作为人类活下去。 "
L44_1.m_Talk_SCN = L45_1
L45_1 = "Du sollst nicht als eine Fee, sondern als Mensch leben."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Tu dois vivre comme un être humain. Pas comme une fée. "
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "ALPHA_ACT3_STAGE3_START@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3900307
L45_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "CEO_NPC_ALPHA_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "……옛날 이야기에서 요정들이 두고 간 아이들이 그랬듯이."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "……おとぎ話に出てくる、妖精が置いていった子どもたちがそうしたように。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Just like the children left behind by the fairies in the old tales..."
L45_1.m_Talk_ENG = L46_1
L46_1 = "……就像以前的故事裡，精靈們留下的孩子那樣。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แบบเด็กๆ ที่ถูกนางฟ้าทอดทิ้งในเรื่องเล่าเก่าแก่..."
L45_1.m_Talk_THA = L46_1
L46_1 = "Giống như những đứa trẻ bị các tiên nữ bỏ lại trong truyện cổ tích..."
L45_1.m_Talk_VTN = L46_1
L46_1 = "……就像古老故事中，被妖精们遗弃的孩子一样。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "... So, wie es die Kinder taten, die in den alten Geschichten von den Feen zurückgelassen wurden."
L45_1.m_Talk_DEU = L46_1
L46_1 = "... Comme les enfants laissés par les fées dans les contes."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
