L49_1 = "ALPHA_ACT3_STAGE3_START@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3900307
L48_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "CEO_NPC_ALPHA_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "그러니 <color=#ffd34c>더 나은 세상을 위해</color>……."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "だから、<color=#ffd34c>より良い世界のために</color>……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Therefore, <color=#ffd34c>for a better world</color>..."
L48_1.m_Talk_ENG = L49_1
L49_1 = "所以，<color=#ffd34c>為了更好的未來</color>……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ดังนั้น <color=#ffd34c>เพื่อโลกที่ดีขึ้น</color>"
L48_1.m_Talk_THA = L49_1
L49_1 = "Do đó, <color=#ffd34c>vì một thế giới tốt đẹp hơn</color>..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "所以，<color=#ffd34c>为了更好的世界</color>……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Also, <color=#ffd34c>für eine bessere Welt</color> ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Alors pour un <color=#ffd34c>monde meilleur</color>..."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "ALPHA_ACT3_STAGE3_START@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3900307
L49_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "CEO_NPC_ALPHA_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "……전부 잊어 버려라."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "……すべて忘れなさい。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "...forget everything."
L49_1.m_Talk_ENG = L50_1
L50_1 = "……這些事你全都忘了吧。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "...ก็ลืมทุกอย่างซะนะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "... hãy quên mọi thứ đi."
L49_1.m_Talk_VTN = L50_1
L50_1 = "把这些……全部忘掉吧。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "... Sollst du alles vergessen."
L49_1.m_Talk_DEU = L50_1
L50_1 = "... Oublie tout."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "ALPHA_ACT3_STAGE3_START@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3900307
L50_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "JIA_CHILD_ALPHA_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "……네, 할아버님. 명심할게요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "……はい、お祖父様。肝に銘じます。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Yes, Grandfather. I’ll take your word to heart."
L50_1.m_Talk_ENG = L51_1
L51_1 = "……是，爺爺，我知道了。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ค่ะ คุณปู่ หนูจะจำใส่ใจไว้เลย"
L50_1.m_Talk_THA = L51_1
L51_1 = "Vâng, ông nội. Cháu sẽ nhớ lời ông."
L50_1.m_Talk_VTN = L51_1
L51_1 = "……好的，爷爷。我会铭记于心的。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "... Jawohl, Großvater. Ich werde es mir merken."
L50_1.m_Talk_DEU = L51_1
L51_1 = "... Très bien grand-père."
L50_1.m_Talk_FRA = L51_1
