L2_1 = "CEO_NPC_ALPHA_NULL"
L1_1.m_CharStrID = L2_1
L2_1 = "그래, 지아야. 어떤 일이 있더라도……. 다시는 그 날개를 펼쳐서는 안 된다."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "そうだ、ユイ。どんなことがあっても……二度とその翅を広げてはならない。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "No matter what, Jia... You must never use your wings."
L1_1.m_Talk_ENG = L2_1
L2_1 = "很好，小佳，無論發生什麼事……都不可以使用你的翅膀！"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ไม่ว่ายังไงนะเจีย... หนูห้ามใช้ปีกนะลูก"
L1_1.m_Talk_THA = L2_1
L2_1 = "Cho dù thế nào đi nữa, Jia ... Cháu không bao giờ được sử dụng đôi cánh của mình."
L1_1.m_Talk_VTN = L2_1
L2_1 = "小佳，以后不管发生什么事……都不要重新展开那个翅膀。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Genau, Jia. Egal, was passiert ... Diese Flügel darfst du nie wieder ausstrecken."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Peu importe la situation... Tu ne dois jamais montrer ces ailes."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
