L15_1 = "ALPHA_ACT3_STAGE3_START@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3900307
L14_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_PRIDE"
L14_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L15_1 = "L"
L14_1.m_Pos = L15_1
L15_1 = "날 상대로 블러핑을 쓰다니 너도 안 본 사이 많이 닳아빠졌구나. 한 방 먹었어."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "私を相手にブラフィングを使うなんて、見ない間にあんたもずいぶん\nやり手になったじゃない。一手食らっちゃったわ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "You got me. I never thought you’d bluff against me."
L14_1.m_Talk_ENG = L15_1
L15_1 = "竟然敢和我玩花招，這麼久不見，你也變得奸詐不少嘛！被你擺了一道！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "เสร็จเธอจนได้ ไม่นึกว่าเธอจะหลอกกันแบบนี้"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tao phục mày rồi. Tao chưa bao giờ nghĩ rằng mày có cửa để phản lại tao."
L14_1.m_Talk_VTN = L15_1
L15_1 = "竟然被你摆了一道，看来这些年没见，你也学会了很多花招呢。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Du hast gegen mich geblufft. Du bist viel gerissener geworden, als ich dich kannte. Damit hast du mir gehörig eins ausgewischt."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ton coup de bluff a fonctionné, on dirait. Je dois reconnaître que tu es plus rusée que la dernière fois."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "ALPHA_ACT3_STAGE3_START@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3900307
L15_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_PRIDE"
L15_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L16_1 = "L"
L15_1.m_Pos = L16_1
L15_1.m_Crash = 10
L16_1 = "그런데 어쩌지? 이번 대국은 내가 이긴 거 같은데?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "でも、どうしよう？　今回の対局は私の勝ちみたいよ？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "But I’m sorry to tell you that I won this round."
L15_1.m_Talk_ENG = L16_1
L16_1 = "可是怎麼辦呢？這局棋好像是我贏了？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "แต่ขอโทษนะที่ต้องบอกว่าตานี้ฉันชนะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Nhưng tao rất tiếc phải nói rằng ván này tao vẫn thắng."
L15_1.m_Talk_VTN = L16_1
L16_1 = "但不管怎样，这次的对局胜利还是属于我！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Aber was nun? Diese Partie habe ich wohl gewonnen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Mais désolée. Je crois que cette fois-ci, j'ai gagné la partie."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
