L18_1 = "FX_CUTSCEN_BATTLEFIELD"
L17_1.m_StartFXSoundName = L18_1
L18_1 = "SPEAR_ALPHA_NULL_SHORT"
L17_1.m_CharStrID = L18_1
L18_1 = "준……!! 정신차려! 준!!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ジュン……しっかりして、ジュン！！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Jun...!! Wake up! JUN!!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "朱恩……！！你醒醒！朱恩！！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "จุน...!! ตื่นสิ! จุน!!"
L17_1.m_Talk_THA = L18_1
L18_1 = "Jun... !! Tỉnh lại! JUN!!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "朱恩……！！快醒醒！朱恩！！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Jun ...!!! Komm zu dir, Jun!!!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Jun...! Réveille-toi ! Jun !"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "ALPHA_ACT3_STAGE3_START@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3900307
L18_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_BGCrash = 30
L18_1.m_fBGCrashTime = 1
L18_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L19_1 = "전열이 무너지면 안 돼요!! 새롬 양이 대신 선봉에 서 주세요!!"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "戦列を崩してはいけません！！　アサネさんが代わりに前に出てください！！"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Maintain positions!! Saerom, take point!!"
L18_1.m_Talk_ENG = L19_1
L19_1 = "保持隊形！！你去代替芷倫站在前鋒的位置！！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "รักษาตำแหน่งไว้!! แซรม ประจำตำแหน่ง!!"
L18_1.m_Talk_THA = L19_1
L19_1 = "Giữ nguyên vị trí !!Saerom, chú ý!!"
L18_1.m_Talk_VTN = L19_1
L19_1 = "不能没有前排！！绫音先顶上去！！"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Die Formation darf nicht gebrochen werden!!! Saerom, gehen Sie stattdessen an die Spitze!"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Nous devons maintenir notre formation ! Saerom ! Placez-vous en tête de ligne."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "ALPHA_ACT3_STAGE3_START@119#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 119
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3900307
L19_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_BGCrash = 15
L19_1.m_fBGCrashTime = 1
L19_1.m_CharStrID = "CHOWON_ALPHA_NULL_NULL"
L20_1 = "실장님, 이게 마지막 탄창이에요!"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "室長、これが最後の弾倉です！"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Chief, this is the last of my ammo!"
L19_1.m_Talk_ENG = L20_1
L20_1 = "室長，這是最後的彈匣了！"
L19_1.m_Talk_TWN = L20_1
L20_1 = "หัวหน้า นี่กระสุนนัดสุดท้ายฉันแล้ว!"
L19_1.m_Talk_THA = L20_1
L20_1 = "Trưởng Phòng, chỉ còn một băng đạn thôi!"
L19_1.m_Talk_VTN = L20_1
L20_1 = "室长，只剩最后一个弹匣了！"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Frau Direktorin, das ist die letzte Munition!"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Jin, c'est notre dernier chargeur !"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "ALPHA_ACT3_STAGE3_START@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
