L20_1.m_BGCrash = 20
L20_1.m_fBGCrashTime = 1
L20_1.m_CharStrID = "LEEJIN_ALPHA_NULL_NULL"
L21_1 = "칫……! 아가씨만 확보할 수 있었어도 이런 불리한 싸움은……!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "まずい……！　お嬢様さえ確保できれば、こんな不利な戦いなんて……！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Tch...! This fight would be a lot easier if we had secured Miss Jia...!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "嘖……！要是有小姐在，戰況也不會對我們如此不利……！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ชิ...! ถ้าเราช่วยคุณเจียมาได้เรื่องคงง่ายขึ้นเยอะ...!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tch...! Cuộc chiến này sẽ dễ dàng hơn rất nhiều nếu chúng ta bảo vệ được tiểu thư Jia...!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "呃……！如果小姐参战，就能避免这种不利的战斗了……！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Hmpf ...! Wenn wir das Fräulein gehabt hätten, wären wir nicht im Nachteil ...!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Zut... ! Si seulement nous avions pu protéger mademoiselle... Nous n'en serions pas arrivés là !"
L20_1.m_Talk_FRA = L21_1
