L26_1 = "L"
L25_1.m_Pos = L26_1
L26_1 = "너라면 알겠지. 내가 원한다면 언제든 저 머저리들을 처리할 수 있다는 걸."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "あんたならわかるでしょ。私が望むならいつでもあの間抜けどもを\n始末できるってことを。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "You know just as well as I do that I can destroy them at will."
L25_1.m_Talk_ENG = L26_1
L26_1 = "你應該很清楚，只要我想，隨時都可以把他們處理掉！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เธอก็รู้ดีพอกับฉันนะว่าฉันทำลายพวกนั้นได้ตามใจนึก"
L25_1.m_Talk_THA = L26_1
L26_1 = "Bọn mày cũng nên biết rằng tao thích nhào bọn mày ra sao tùy thích. "
L25_1.m_Talk_VTN = L26_1
L26_1 = "你应该很清楚吧。我如果愿意，可以随时处理掉那些蠢货。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Du weißt am besten, dass ich diese Würmer jederzeit vernichten kann, wenn ich will."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Tu dois savoir que je suis capable de tous les éliminer."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "ALPHA_ACT3_STAGE3_START@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3900307
L26_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L26_1.m_bWaitClick = true
