L26_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L27_1 = "L"
L26_1.m_Pos = L27_1
L27_1 = "그러니 너에게 마지막으로 선택의 기회를 줄게."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "だから、あんたに最後のチャンスを与えるわ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "So, I’ll give you one last chance, Jia."
L26_1.m_Talk_ENG = L27_1
L27_1 = "我要給你最後一次選擇的機會。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ดังนั้น ฉันจะให้โอกาสเธอเป็นครั้งสุดท้ายนะเจีย"
L26_1.m_Talk_THA = L27_1
L27_1 = "Vì vậy, tao sẽ cho mày một cơ hội cuối cùng, Jia."
L26_1.m_Talk_VTN = L27_1
L27_1 = "所以，我给你最终选择的机会。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Also gebe ich dir die letzte Wahl."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Donc je vais te donner une dernière chance."
L26_1.m_Talk_FRA = L27_1
