L29_1.m_Crash = 10
L30_1 = "저것들을 살리고 싶다면, 나를 따라와."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "あいつらを助けたいなら、私についてきなさい。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "If you want them to keep breathing, come with me."
L29_1.m_Talk_ENG = L30_1
L30_1 = "想救他們的話，你就跟我走。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ถ้ายังอยากให้พวกนั้นมีชีวิตอยู่ ก็มากับฉันซะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nếu mày muốn bọn chúng còn thở, đến chỗ tao."
L29_1.m_Talk_VTN = L30_1
L30_1 = "如果你想救那些人，就跟我来。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Folge mir, wenn du sie retten willst."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Si tu veux qu'ils restent en vie, suis-moi."
L29_1.m_Talk_FRA = L30_1
