L32_1 = 0.01
L30_1[L31_1] = L32_1
L31_1 = "그게 네 인생의 최후의 선택이 되는 거야."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "それがあんたの人生で最後の選択になるわ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "And that will be the last choice you’ll ever make."
L30_1.m_Talk_ENG = L31_1
L31_1 = "這是你人生中最後一次做選擇。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "และนั่นจะเป็นการเลือกครั้งสุดท้ายในชีวิตเธอ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Và đó sẽ là sự lựa chọn cuối cùng mà mày sẽ từng thực hiện."
L30_1.m_Talk_VTN = L31_1
L31_1 = "这将成为你人生中最后的一个选择，以后你就再也不用考虑选择的问题了。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Das wird die letzte Entscheidung deines Lebens sein."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Ce sera ta dernière décision."
L30_1.m_Talk_FRA = L31_1
