L31_1.m_Crash = 10
L32_1 = "물론 반항하지 못하게 뇌 세척은 해야겠지만……. 죽는 것보단 낫지 않겠어?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "もちろん反抗できないように脳の洗浄は必要だけど……\n死ぬよりはマシじゃない？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Of course, I’ll have to brainwash you to never disobey me again... But that’s better than dying, isn’t it?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "當然我會替你洗腦，以免你反抗……但總比死來得好吧？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ซึ่งแน่นอน ฉันต้องล้างสมองจนเธอแข็งขืนอีกไม่ได้... แต่ก็ดีกว่าตาย จริงมั้ย?"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tất nhiên, tao sẽ phải tẩy não để mày không bao giờ làm trái lời tao nữa... Nhưng điều đó vẫn tốt hơn là chết, phải không nhỉ?"
L31_1.m_Talk_VTN = L32_1
L32_1 = "当然我为了防止你反抗，会给你洗脑……但至少比死了要好吧？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich werde dir eine Gehirnwäsche verpassen müssen, damit du keinen Widerstand leistest ... aber besser als der Tod ist es allemal, oder?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Tu subiras un lavage de cerveau, mais... C'est mieux que de mourir, non ?"
L31_1.m_Talk_FRA = L32_1
