L37_1 = "L"
L36_1.m_Pos = L37_1
L37_1 = "어차피 명령하는 사람이 아버지에서 나로 바뀌는 것뿐이잖아?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "どうせ命令する人が父さんから私に変わるだけでしょ？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Think of it as just replacing Father with me."
L36_1.m_Talk_ENG = L37_1
L37_1 = "不過就是下令的人從爸換成我而已，不是嗎？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ลองคิดว่าฉันเป็นพ่อสิ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Hãy coi đó như việc thay Cha ở bên cạnh tao."
L36_1.m_Talk_VTN = L37_1
L37_1 = "仅仅只是下命令的人，从父亲变成我而已，不是吗？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Der Befehlshaber ändert sich doch bloß von Vater zu mir."
L36_1.m_Talk_DEU = L37_1
L37_1 = "C'est juste que ce ne sera plus mon père qui donnera les ordres, mais moi !"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
