L38_1 = "L"
L37_1.m_Pos = L38_1
L37_1.m_Crash = 10
L38_1 = "넌 그냥 시키는 대로 얌전히 따르기만 하면 돼."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "あなたは言われたとおり、大人しく従えばいいのよ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "All you need to do is obey my every will."
L37_1.m_Talk_ENG = L38_1
L38_1 = "你只需要乖乖照做就好。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "เธอก็ต้องทำตามทุกความตั้งใจของฉัน"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tất cả những gì mày cần làm là tuân theo mọi ý muốn của tao."
L37_1.m_Talk_VTN = L38_1
L38_1 = "你只要乖乖服从命令就好。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Du musst einfach nur brav gehorchen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Toi, tu n'aurais qu'à exécuter."
L37_1.m_Talk_FRA = L38_1
