L41_1.m_StartFXSoundName = L42_1
L42_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "다른 사람의 말은 결국 자네가 살면서 참고할 이정표지, 목적지가 아니야."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "他人の言うことは、君が生きていく中で参考できる道しるべにはなるが、\n目的地にはなれないんだ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "What I'm trying to say is that what others say is a reference point in your life, not your final destination."
L41_1.m_Talk_ENG = L42_1
L42_1 = "其他人說的話，不能成為你的終點或目的地。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ที่ผมอยากบอกก็คือ สิ่งที่คนอื่นพูดก็เป็นแค่จุดอ้างอิงในชีวิตคุณเท่านั้นแหละ และไม่ใช่จุดหมายปลายทาง"
L41_1.m_Talk_THA = L42_1
L42_1 = "Điều tôi muốn nói là những gì người khác nói là điểm tham chiếu trong cuộc sống của cô, chứ không phải là điểm đến cuối cùng của cô."
L41_1.m_Talk_VTN = L42_1
L42_1 = "别人说的那些话，终究只是你在生活中值得借鉴的指示牌，而不是终点站。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Die Worte anderer sind für dich ein Wegweiser, aber nicht das Ziel."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Dis-toi que les paroles des autres ne sont que des repères, des marques au sol pour te guider."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "ALPHA_ACT3_STAGE3_START@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3900307
L42_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "목적지를 정하는 건 자네 자신의 마음에 달렸지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "目的地を決めるのは君の心次第ってことだよ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Whichever direction you choose to go is entirely up to your heart."
L42_1.m_Talk_ENG = L43_1
L43_1 = "只有你的心能夠決定你的目的地！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ส่วนคุณจะเลือกเดินไปทางไหน นั่นต้องแล้วแต่ใจคุณเลย"
L42_1.m_Talk_THA = L43_1
L43_1 = "Cô chọn hướng nào cũng hoàn toàn xuất phát từ trái tim cô."
L42_1.m_Talk_VTN = L43_1
L43_1 = "决定终点站到底在哪的，是你的内心。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Wo du dein Ziel steckst, hängt von deinem Herzen ab."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Mais ton but, le sens de ta vie... c'est à toi de le trouver."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "ALPHA_ACT3_STAGE3_START@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3900307
L43_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "JIA_ALPHA_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "마음……."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "私の心……"
L43_1.m_Talk_JPN = L44_1
L44_1 = "My heart..."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我的心……"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ใจฉันเหรอคะ..."
L43_1.m_Talk_THA = L44_1
L44_1 = "Trái tim tôi..."
L43_1.m_Talk_VTN = L44_1
L44_1 = "我的内心……"
L43_1.m_Talk_SCN = L44_1
L44_1 = "... Mein Herz?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "À moi... ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "ALPHA_ACT3_STAGE3_START@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3900307
L44_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_Face = "UNIT_DESPAIR"
L45_1 = "JIA_ALPHA_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "그렇지만 사장님, 전 여태까지 할아버님 말씀대로만 해 왔는데……."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "でも社長、私はこれまでお祖父様の言うとおりに生きてきたのに……"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Th-then... I’ve lived my life according to Grandfather’s words all this time..."
L44_1.m_Talk_ENG = L45_1
L45_1 = "可是老闆，我一直以來都是按著爺爺的話而活……"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ถะ-ถ้างั้น... ฉันใช้ชีวิตตามคำสอนของคุณปู่มาตลอด..."
L44_1.m_Talk_THA = L45_1
L45_1 = "V-vậy... tôi đã sống cả đời theo di nguyện của Ông..."
L44_1.m_Talk_VTN = L45_1
L45_1 = "可是老板，我一直都是按照爷爷说过的话生活……"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Aber, Boss, ich habe bisher nur getan, was mein Großvater wollte ..."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Jusqu'à maintenant, je n'ai fait qu'écouter mon grand-père..."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "ALPHA_ACT3_STAGE3_START@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3900307
L45_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "JIA_ALPHA_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "이제 와서 스스로 뭔가를 선택할 수 있을까요?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "今さら自分で何かを決めることができるのでしょうか？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Will I still be able to make choices by myself?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "現在我還能夠自己做選擇嗎？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แล้วฉันจะยังเลือกอะไรเองได้มั้ยคะ?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Liệu tôi có thể tự mình lựa chọn không?"
L45_1.m_Talk_VTN = L46_1
L46_1 = "到现在还能自己选择吗？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Könnte ich so spät noch selbst entscheiden?"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Vous pensez que je vais réussir à faire des choix par moi-même ?"
L45_1.m_Talk_FRA = L46_1
