L48_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "걱정 말게, 지아 양. 나는 자네가 잘할 거라고 믿고 있어."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "心配はいらないぞ、ユイ君。私は君ならできると信じている。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Don’t worry, Jia. I believe you’ll do great."
L47_1.m_Talk_ENG = L48_1
L48_1 = "沒事的，沈佳！我相信你可以的！"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ไม่ต้องห่วงนะเจีย ผมรู้ว่าคุณต้องทำได้ดีมากแน่"
L47_1.m_Talk_THA = L48_1
L48_1 = "Đừng lo lắng, Jia. Tôi biết là cô sẽ làm rất tốt."
L47_1.m_Talk_VTN = L48_1
L48_1 = "别担心，我相信你可以做得很好。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Keine Bange, Jia. Ich glaube an dich."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Ne t'inquiète pas Jia. Je crois en toi."
L47_1.m_Talk_FRA = L48_1
