L4_1 = "고모님, 전 이미 오래 전에 마음을 정했어요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "叔母様、私はずっと前から心を決めました。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Auntie, I’ve made up my mind a long time ago."
L3_1.m_Talk_ENG = L4_1
L4_1 = "姑姑，我很久以前就已經做好決定了。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "น้าคะ หนูตัดสินใจตั้งนานแล้วค่ะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Cô à, cháu đã quyết định từ lâu rồi."
L3_1.m_Talk_VTN = L4_1
L4_1 = "姑姑，我在很久以前就下定了决心。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Tante, ich habe mich schon vor langer Zeit entschieden."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Vous savez Cecilia, ça fait déjà longtemps que j'ai pris ma décision."
