L8_1 = "C_L_M_I"
L7_1.m_Pos = L8_1
L8_1 = "……아주 끝까지 날 얕잡아 보는구나, 이 역겨운 괴물 계집애."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "……最後の最後まで私を舐めやがって。この忌々しい化け物が。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "You still underestimate me until the very end, you monster."
L7_1.m_Talk_ENG = L8_1
L8_1 = "……看來你這個令人作噁的怪物，還是沒把我放眼裡。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แกนี่มันสบประมาทฉันจนถึงที่สุดจริงๆ นะนังตัวประหลาด"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cho đến cuối cùng mày vẫn đánh giá tao quá thấp, đồ quái vật."
L7_1.m_Talk_VTN = L8_1
L8_1 = "……到最后都要小看我吗？你这个怪胎。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "... Du verspottest mich bis zum Ende, du elendiges Monsterweib."
L7_1.m_Talk_DEU = L8_1
L8_1 = "... Tu continues à me sous-estimer on dirait. Sale monstre."
L7_1.m_Talk_FRA = L8_1
