L9_1 = "날 쓰러트려? 어떻게?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "私を倒す？　どうやって？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Defeat me? Are you sure?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "想打倒我？怎麼做？"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เอาชนะฉันเหรอ? มั่นหน้านักเหรอ?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Đánh bại tao? Mày có chắc không?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "你凭什么打败我？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Du, mich besiegen? Wie das?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Tu veux m'éliminer ? Et pourrais-je savoir comment ?"
L8_1.m_Talk_FRA = L9_1
