L9_1.m_Pos = "C"
L10_1 = "체크메이트야! 이 상황에서 날 어떻게 한다고 저 머저리들이 무사할 수 있을 것 같아?!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "チェックメイトよ！　この状況であいつらが無事で済むとでも？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "It’s checkmate! Do you really think defeating me will change what happens to your idiot friends?!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "將軍！你敢動我一根寒毛的話，你以為他們會沒事嗎？！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "นี่รุกจนแล้ว! คิดเหรอว่าเอาชนะฉันแล้วจะช่วยเพื่อนโง่ๆ ของแกได้น่ะ!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Chiếu tướng! Mày tưởng thực sự đánh bại tao sẽ thay đổi số phận của những đứa bạn ngu ngốc của mày à?!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "我已经把你将死了！就算在这种情况下把我杀掉，那些蠢货们也没办法平安无事！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Schachmatt! Was könntest du gegen mich schon tun, um diese Würmer zu retten?!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "J'ai gagné ! Échec et mat ! Tu penses pouvoir sauver ces imbéciles en m'éliminant ?"
L9_1.m_Talk_FRA = L10_1
