L10_1[L11_1] = L12_1
L11_1 = "m_CharScaleTime"
L12_1 = 0.1
L10_1[L11_1] = L12_1
L11_1 = "너한테 선택지 따위는 없어! 닥치고 패배를 받아들이라고!"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "あんたに選択肢なんて無いわ！　黙って敗北を受け入れなさい！"
L10_1.m_Talk_JPN = L11_1
L11_1 = "You don’t have a choice in this! Admit your defeat!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "你沒有選擇的餘地！閉上你的嘴，承認失敗吧！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เรื่องนี้แกไม่มีทางเลือกด้วยซ้ำ! ยอมรับความพ่ายแพ้ซะเถอะ!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Mày không có quyền lựa chọn trong việc này! Thừa nhận thất bại đi!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "你已经没有多余的选项了！还是闭上嘴接受失败吧！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Du hast keine Wahl! Halt die Klappe und sieh deine Niederlage ein!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Tu n'as pas le choix ! Tu dois reconnaître que tu as perdu !"
