L13_1 = "ALPHA_ACT3_STAGE3_START@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3900307
L12_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_PRIDE"
L13_1 = "JIA_ALPHA_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "그건 제 마음에 들지 않는 선택지네요."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "それは私にとって気に入らない選択肢ですね。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I’m afraid that won’t work with me."
L12_1.m_Talk_ENG = L13_1
L13_1 = "這個選擇不是我想要的！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "เกรงว่าจะไม่ได้ผลกับหนูนะคะ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Cháu e rằng điều đó sẽ không hiệu quả với cháu đâu."
L12_1.m_Talk_VTN = L13_1
L13_1 = "但那个选项我不满意。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Diese Wahl gefällt mir leider nicht."
L12_1.m_Talk_DEU = L13_1
L13_1 = "C'est un choix qui ne me plaît pas."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "ALPHA_ACT3_STAGE3_START@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3900307
L13_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_LAUGH"
L14_1 = "JIA_ALPHA_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L14_1 = "그래서 결정했어요. 제 마음에 드는 선택지를 만들기로."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "だから決めました。自分のお気に入りの選択肢を作ると。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I’ve decided... to make my own choice."
L13_1.m_Talk_ENG = L14_1
L14_1 = "我決定要選擇我真正想要的！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เพราะหนูตัดสินใจ... เลือกเองแล้วค่ะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Cháu đã quyết định... đưa ra lựa chọn của riêng mình."
L13_1.m_Talk_VTN = L14_1
L14_1 = "所以我决定，创造我喜欢的选项。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Also habe ich mich entschieden, eine Wahl zu erschaffen, die mir gefällt."
L13_1.m_Talk_DEU = L14_1
L14_1 = "J'ai donc pris ma décision. Un choix qui m'appartient."
L13_1.m_Talk_FRA = L14_1
