L18_1 = "m_VoiceFileName"
L19_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_TRAILER_1"
L17_1[L18_1] = L19_1
L18_1 = "……죄송해요, 할아버님."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "……申し訳ございません、お祖父様。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "...Forgive me, Grandfather."
L17_1.m_Talk_ENG = L18_1
L18_1 = "……爺爺對不起。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "...ขอโทษนะคะคุณปู่"
L17_1.m_Talk_THA = L18_1
L18_1 = "...Cho cháu xin lỗi, Ông nội."
L17_1.m_Talk_VTN = L18_1
L18_1 = "……对不起，爷爷。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "... Verzeihung, Großvater."
L17_1.m_Talk_DEU = L18_1
L18_1 = "... Pardonnez-moi, grand-père."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "ALPHA_ACT3_STAGE3_START@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 3900307
L18_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "m_VoiceFileName"
L20_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_TRAILER_2"
L18_1[L19_1] = L20_1
L19_1 = "할아버님께서는 저를 위해 그 날개를 접어두라고 하셨지만……."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "お祖父様は私のために、その翅を畳んでおきなさいとおっしゃいましたが……"
L18_1.m_Talk_JPN = L19_1
L19_1 = "I know you told me to hide my wings for my own sake..."
L18_1.m_Talk_ENG = L19_1
L19_1 = "雖然爺爺希望我收起翅膀……"
L18_1.m_Talk_TWN = L19_1
L19_1 = "หนูทราบดีค่ะว่าคุณปู่อยากให้หนูซ่อนปีกไว้จะได้ดีกับตัวเอง..."
L18_1.m_Talk_THA = L19_1
L19_1 = "Cháu biết ông đã bảo cháu giấu đi đôi cánh vì muốn tốt cho cháu..."
L18_1.m_Talk_VTN = L19_1
L19_1 = "爷爷曾说过，要我为了自己隐藏起翅膀……"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Sie sagten zu mir, dass ich mir selbst zuliebe diese Flügel geschlossen halten soll,"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Vous m'avez interdit d'ouvrir mes ailes mais..."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
