L20_1 = "m_VoiceFileName"
L21_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_TRAILER_3"
L19_1[L20_1] = L21_1
L20_1 = "저는 모두를 구하기 위해."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "私はみんなを救うために。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "But to save everyone..."
L19_1.m_Talk_ENG = L20_1
L20_1 = "但為了救大家，"
L19_1.m_Talk_TWN = L20_1
L20_1 = "แต่เพื่อช่วยทุกคน..."
L19_1.m_Talk_THA = L20_1
L20_1 = "Nhưng để cứu mọi người..."
L19_1.m_Talk_VTN = L20_1
L20_1 = "但为了拯救大家。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "aber ich werde, um alle zu retten,"
L19_1.m_Talk_DEU = L20_1
L20_1 = "C'est pour sauver mes amis."
L19_1.m_Talk_FRA = L20_1
