L20_1.m_fTalkTime = 0.03
L21_1 = "……そして、より良い世界のために。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "and for a better world..."
L20_1.m_Talk_ENG = L21_1
L21_1 = "……也為了更好的未來，"
L20_1.m_Talk_TWN = L21_1
L21_1 = "และเพื่อโลกที่ดีขึ้น..."
L20_1.m_Talk_THA = L21_1
L21_1 = "và vì một thế giới tốt đẹp hơn..."
L20_1.m_Talk_VTN = L21_1
L21_1 = "……还有为了更好的世界。"
