L30_1 = "이, 이거 봐! 오빠! 나 혼자 스포트라이트를 받고 있어!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "こ、これを見て、お兄ちゃん！　私一人でスポットライトを浴びてるよ！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "C-come look at this! Gabriel! I’m in the limelight!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "哥哥你看！聚光燈打在我身上欸！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "มะ-มาดูนี่สิ! กาเบรียล! มีไฟส่องฉันด้วยล่ะ!"
L29_1.m_Talk_THA = L30_1
L30_1 = "N-nhìn đi kìa! Gabriel! Em đang ở trong ánh đèn sân khấu!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "你、你快看啊！哥哥！有聚光灯照到了我身上！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "S-schau, Brüderchen! Ich stehe alleine im Scheinwerferlicht!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Regarde Gabriel ! Les feux sont braqués sur moi !"
L29_1.m_Talk_FRA = L30_1
