L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "으음……? 내 검이 무지개빛으로 빛나다니?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "うむ……？　私の剣が虹色に輝いている？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Hmm? My sword... It’s glowing in all seven colors?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "嗯……？是我的劍發出七彩之光嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "หืมมม? ดาบข้า... มันเรืองแสงเจ็ดสีเลย?"
L33_1.m_Talk_THA = L34_1
