L49_1 = "아얏! 아야야! 뭐가 하늘에서 막 떨어져!?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "痛っ！　いたたた！　空から何か落ちてきた！？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Ow! Ouch! There’s something falling from the sky."
L48_1.m_Talk_ENG = L49_1
L49_1 = "哇！欸欸欸！好像有東西從天而降欸？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "โอ๊ย! โอ๊ย! มีอะไรตกมาจากฟ้าด้วย"
L48_1.m_Talk_THA = L49_1
L49_1 = "Ồ! Ồ! Có thứ gì đó từ trên trời rơi xuống."
L48_1.m_Talk_VTN = L49_1
L49_1 = "啊呀！天上有东西掉下来了！？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Aua! Autsch! Da fällt was vom Himmel?!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ah ! Aaah ! Mais il y a des trucs qui tombent !"
L48_1.m_Talk_FRA = L49_1
