L5_1 = "ALPHA_ACT3_STAGE3_START@204#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 204
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3900307
L4_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L5_1 = "설마, 유전자 구조 설계 과정에서 삽입된 암시를 스스로 깨 버렸다고……?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "まさか、遺伝子構造設計の過程で入れた暗示を自ら破った……？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "You couldn’t have... You freed yourself from the code embedded in your DNA...?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "難道是她自己解除掉基因組成設計過程中插入的暗號……？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แกไม่น่าจะ... นี่ปลดปล่อยตัวเองจากรหัสที่ฝังในไว้ในDNAอย่างนั้นเรอะ...?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Không thể nào... Mày đã giải phóng mình khỏi mã nhúng trong DNA của mình sao...?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "难道她自己打破了遗传因子结构设计过程中植入的暗示……？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Herrje, hast du den Bann eigenhändig gebrochen, der während der Konstruktion der Genstrukturen in dich eingefügt wurde ...?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Impossible... Tu as réussi à réveiller cette idée introduite durant le processus de création de la structure de génome humain...?"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "ALPHA_ACT3_STAGE3_START@205#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 205
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3900307
L5_1.m_CutScenStrID = "ALPHA_ACT3_STAGE3_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_BGCrash = 20
L5_1.m_fBGCrashTime = 1
L5_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L6_1 = "말도 안 돼……!! 이미 의지로 어쩔 수 있는 영역이 아니잖아!!"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "あり得ない……！！　意志でどうにかできる領域じゃないわ！！"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Impossible...!! That can’t be done by pure will!!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "這怎麼可能……！！這不是靠意志力就可以辦到的吧！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เป็นไปไม่ได้...!! แค่ความมุ่งมั่นอย่างเดียวจะทำได้ยังไง!!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Không thể nào...!! Ý chí thuần túy không thể làm được điều đó!!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "不可能……！！这绝对不是靠自身意志就能控制的！！"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Unfassbar ...!!! Das geht doch beim besten Willen nicht!!!"
L5_1.m_Talk_DEU = L6_1
L6_1 = "C'est pas vrai... ! Comment as-tu pu... simplement par ta volonté ?"
L5_1.m_Talk_FRA = L6_1
