L8_1 = "m_VoiceFileName"
L9_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_TRAILER_6"
L7_1[L8_1] = L9_1
L8_1 = "JIA_ALPHA_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "<color=#ffd34c>사용해도 된다</color>고 하는 할아버님 목소리를 들었다고 상상했거든요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "<color=#ffd34c>使ってもいい</color>というお祖父様の声を想像しました。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I imagined that Grandfather’s voice told me that <color=#ffd34c>I’m allowed to use them</color>."
L7_1.m_Talk_ENG = L8_1
L8_1 = "我只是想像聽到爺爺跟我說，<color=#ffd34c>可以使用</color>。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "หนูจินตนาการว่าเสียงของคุณปู่บอกว่า<color=#ffd34c>หนูใช้มันได้</color>ค่ะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi đã tưởng tượng rằng giọng nói của Ông nội nói với tôi rằng <color=#ffd34c>tôi được phép sử dụng chúng</color>."
L7_1.m_Talk_VTN = L8_1
L8_1 = "我想象自己听到了爷爷说出<color=#ffd34c>“可以用哦？”</color>的声音。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ich habe mir vorgestellt, Großvaters Stimme gehört zu haben, dass ich sie <color=#ffd34c>benutzen darf</color>."
L7_1.m_Talk_DEU = L8_1
L8_1 = "J'ai imaginé que grand-père <color=#ffd34c>m'autorisait</color> à les utiliser."
L7_1.m_Talk_FRA = L8_1
