L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALPHA_CA_JIA_TRAILER_7"
L8_1[L9_1] = L10_1
L9_1 = "JIA_ALPHA_NULL_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "고모님이 정확한 성문을 들려 주신 덕분에 상상하기 어렵지 않았어요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "叔母様が正確な声紋を聞かせてくれたおかげで、想像しやすかったです。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Since you spoke in his voice, the rest wasn’t that hard."
L8_1.m_Talk_ENG = L9_1
L9_1 = "多虧姑姑提供爺爺的聲音，所以想像起來不會太困難。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ในเมื่ออาบอกหนูแล้วว่าวลีกระตุ้นคืออะไร ที่เหลือก็ไม่ยากนะคะ"
L8_1.m_Talk_THA = L9_1
L9_1 = "Vì cô đã cho cháu biết cụm từ kích hoạt là gì, việc còn lại không khó."
L8_1.m_Talk_VTN = L9_1
L9_1 = "多亏姑姑告诉了我触发条件，所以剩下的也没那么难。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Da Sie mir die exakte Glottis seiner Stimme gezeigt haben, war das nicht schwer."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Ce n'était pas difficile, car vous m'avez permis d'entendre de nouveau sa voix."
L8_1.m_Talk_FRA = L9_1
