L10_1.m_fBGCrashTime = 1
L10_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L11_1 = "그딴 농담 집어치워!! 상상한다고 풀릴 정도의 암시일 것 같아, 그게?!"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ふざけた冗談はやめなさい！！　\nそれが想像で解ける程度の暗示だと思ってるの！？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Enough joking around!! You think that it can be broken just by imagining it?!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "你在跟我開什麼玩笑！！光靠想像就可以解除暗號？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เลิกเล่นกันซะที!! คิดว่าแค่ใช้จินตนาการจะทำลายมั้นได้เหรอ?!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Đùa thế đủ rồi !! Mày nghĩ chỉ tưởng tượng là đủ để phá giải phong ấn sao?!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "收起你的玩笑！！你真的以为靠想象就能解除控制吗！！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Mach keine Scherze!!! Dieser Bann wird doch nicht allein durch Vorstellungskraft aufgehoben!!!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Cesse de mentir ! Ce genre de chose ne se libère par juste par la simple imagination !"
L10_1.m_Talk_FRA = L11_1
