L11_1[L12_1] = L13_1
L12_1 = "JIA_ALPHA_NEXT_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "진심을 담아서 상상하면 돼요."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "心を込めて想像すればできます。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I just have to imagine it with all my heart."
L11_1.m_Talk_ENG = L12_1
L12_1 = "只要發自內心去想像就可以辦得到。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "หนูก็แค่ต้องทุ่มทั้งใจจินตนาการไปค่ะ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Cháu chỉ cần tưởng tượng nó với tất cả lòng chân thành mà thôi."
L11_1.m_Talk_VTN = L12_1
L12_1 = "如果用自己的真心去想象，就可以哦。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Man muss es sich von ganzem Herzen wünschend vorstellen."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Si, à condition d'être sincère."
L11_1.m_Talk_FRA = L12_1
