L15_1.m_CharStrID = "CECILIA_NPC_ALPHA_NULL"
L16_1 = "그래……! 그렇게 나와야지! 역시 네 잘난 면상은 흔적도 없이 뭉개 버리는 게 맞아!!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "そうね……！　そうこなくちゃ！\nやっぱりあんたのその偉そうなツラは跡形もなく潰してやるべきだわ！！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Yes...! There you go! I knew I was going to crush that pretty face of yours!!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "很好……！這樣才對嘛！果然要打爛你那張囂張的臉才可以！！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ได้...! เอาเลย! ฉันกะจะขยี้หน้าสวยๆ ของแกอยู่แล้ว!!"
L15_1.m_Talk_THA = L16_1
L16_1 = "Đúng...! Làm đi! Tao biết là mình sẽ nghiền nát khuôn mặt xinh đẹp đó của mày!!"
L15_1.m_Talk_VTN = L16_1
L16_1 = "没错……！就是这样！就是这副表情！我要把你这张骄傲的脸踩在脚底下彻底碾碎！！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ja ...! So ist es gut! Deine arrogante Fresse werde ich in Grund und Boden polieren, so wie es sich gehört!!!"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Bien sûr ! Continue comme ça ! Je vais broyer ton beau visage innocent !"
L15_1.m_Talk_FRA = L16_1
