L17_1 = "JIA_ALPHA_NEXT_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "글쎄요. 그건 상상하시는 만큼 쉽지 않을 것 같네요, 고모님."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "そうですか。それは想像するほど簡単ではないと思いますよ、叔母様。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Well, I don’t think it’ll be as easy as you think, Auntie."
L16_1.m_Talk_ENG = L17_1
L17_1 = "這我不確定，可能沒有想像中容易，姑姑。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แหม หนูว่าคงไม่ง่ายอย่างที่คุณน้าคิดนะคะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Chà, cháu không nghĩ mọi chuyện sẽ dễ dàng như cô tưởng đâu."
L16_1.m_Talk_VTN = L17_1
L17_1 = "是吗。但这个可没有想象中那么容易哦，姑姑。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Tja. Das wird nicht so leicht werden, wie Sie es sich vorstellen, Tante."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Peut-être, mais ce ne sera pas aussi facile que ce que vous croyez."
L16_1.m_Talk_FRA = L17_1
