L17_1[L18_1] = L19_1
L18_1 = "지금은 저도…… 최선이라는 걸 다해 볼 테니까요!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "今回は私も……最善を尽くしてみますから！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Because I will also... do my best to stop you!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "因為現在……我也決定要盡我最大的努力！"
L17_1.m_Talk_TWN = L18_1
